  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div class="page-shell">
      <header>
        <p class="eyebrow">Feline field notes</p>
        <h1>Cat FAQ</h1>
        <p class="intro">
          Quick answers to common questions about cat behavior, care, and daily
          life with a curious companion.
        </p>
      </header>

      <main id="main-content" tabindex="-1"></main>

      <footer>
        <p>Answers are general guidance; contact a veterinarian for medical concerns.</p>
      </footer>
    </div>

    <script>
      const faqItems = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats often purr when they are relaxed, but purring can also be self-soothing during stress or discomfort. Look at the whole context: posture, appetite, breathing, and behavior all matter."
        },
        {
          question: "How much sleep do cats need?",
          answer:
            "Most adult cats sleep 12 to 16 hours a day, while kittens and seniors may sleep even more. Short bursts of activity at dawn and dusk are normal because cats are naturally crepuscular."
        },
        {
          question: "Should indoor cats have enrichment?",
          answer:
            "Yes. Puzzle feeders, climbing spaces, scratching posts, window views, and daily play help indoor cats exercise their bodies and use their hunting instincts in safe ways."
        },
        {
          question: "Why does my cat knead blankets?",
          answer:
            "Kneading is a comforting behavior that begins in kittenhood. Adult cats may knead soft surfaces when they feel secure, are settling down to rest, or are marking a familiar spot with scent glands in their paws."
        },
        {
          question: "How often should a litter box be cleaned?",
          answer:
            "Scoop at least once a day and refresh the litter regularly. A clean box supports good habits, reduces odors, and makes it easier to notice changes that could signal a health issue."
        }
      ];

      function FAQItem({ question, answer }, index) {
        const item = document.createElement("div");
        const buttonId = `faq-question-${index}`;
        const detailsId = `faq-answer-${index}`;

        item.className = "example";
        item.innerHTML = `
          <button
            class="question"
            id="${buttonId}"
            type="button"
            aria-expanded="false"
            aria-controls="${detailsId}"
          >
            <span>${question}</span>
            <span class="indicator" aria-hidden="true">+</span>
          </button>
          <div
            class="details"
            id="${detailsId}"
            role="region"
            aria-labelledby="${buttonId}"
            hidden
          >
            <p>${answer}</p>
          </div>
        `;

        const button = item.querySelector(".question");
        const details = item.querySelector(".details");
        const indicator = item.querySelector(".indicator");

        button.addEventListener("click", () => {
          const isExpanded = button.getAttribute("aria-expanded") === "true";

          button.setAttribute("aria-expanded", String(!isExpanded));
          details.hidden = isExpanded;
          indicator.textContent = isExpanded ? "+" : "-";
        });

        return item;
      }

      function FAQApp({ items }) {
        const section = document.createElement("section");
        const heading = document.createElement("h2");
        const list = document.createElement("div");

        section.setAttribute("aria-labelledby", "faq-heading");
        heading.id = "faq-heading";
        heading.textContent = "Frequently asked questions";
        list.className = "faq-list";

        items.forEach((item, index) => {
          list.append(FAQItem(item, index + 1));
        });

        section.append(heading, list);
        return section;
      }

      document.querySelector("#main-content").append(FAQApp({ items: faqItems }));
    </script>
  </body>
</html>
